INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente de 62 anos, DM2 e HAS, admitido com IAMssST de alto risco (GRACE 150). Durante a cineangiocoronariografia, identifica-se lesão de 90% em Tronco de Coronária Esquerda (TCE) não protegida, com escore SYNTAX de 34. Qual a melhor estratégia de revascularização para este paciente, considerando as diretrizes atuais para redução de eventos cardiovasculares maiores a longo prazo?", "options": {"a": "Intervenção Coronária Percutânea (ICP) com stent farmacológico apenas.", "b": "Cirurgia de Revascularização do Miocárdio (CRVM).", "c": "Tratamento clínico otimizado isolado devido ao alto risco cirúrgico.", "d": "ICP com balão de contrapulsação intra-aórtico sem stent.", "e": "Trombólise química imediata."}, "answer": "b", "rationale": "Para lesões de TCE com escore SYNTAX elevado (> 32), a CRVM é superior à ICP na redução de novos eventos isquêmicos e necessidade de nova revascularização, sendo recomendação classe I. A ICP é alternativa em SYNTAX baixo ou risco cirúrgico proibitivo.", "option_rationales": {"a": "Incorreta. SYNTAX elevado favorece cirurgia.", "b": "Correta. Padrão-ouro para TCE complexo.", "c": "Incorreta. Revascularização é mandatória em lesão crítica estável/instável.", "d": "Incorreta. Balão não substitui revascularização.", "e": "Incorreta. Fibrinólise não é indicada em IAMssST."}, "difficulty": "dificil", "tags": ["Cardiologia", "TCE", "CRVM", "SYNTAX"]}', 56, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um homem de 58 anos apresenta dispneia súbita e dor torácica tipo pleurítica 3 dias após um IAM anterior extenso. Ao exame: PA 90/60 mmHg, turgência jugular, pulmões limpos, e nota-se um atrito pericárdico na borda esternal esquerda. O ECG mostra alternância elétrica. Qual a complicação mecânica mais provável e a conduta imediata?", "options": {"a": "Ruptura de músculo papilar; cirurgia de troca valvar.", "b": "Ruptura de parede livre do VE com tamponamento cardíaco; pericardiocentese de alívio e cirurgia de emergência.", "c": "Comunicação interventricular (CIV) pós-infarto; implante de dispositivo oclusor.", "d": "Aneurisma de ponta de VE; anticoagulação plena.", "e": "Síndrome de Dressler; prednisona oral."}, "answer": "b", "rationale": "A tríade de Beck (hipotensão, turgência jugular e abafamento de bulhas - embora o atrito possa ocorrer se for ruptura contida ou exsudato), associada a pulmões limpos e alternância elétrica no ECG após infarto extenso, aponta para ruptura de parede livre e tamponamento. É uma emergência fatal que exige drenagem e reparo cirúrgico.", "option_rationales": {"a": "Incorreta. Papilar causa edema agudo de pulmão (sopro holossistólico).", "b": "Correta. Complicação mecânica catastrófica do infarto.", "c": "Incorreta. CIV causa sopro e congestão pulmonar.", "d": "Incorreta. Aneurisma é crônico.", "e": "Incorreta. Dressler é tardio e raramente causa choque imediato."}, "difficulty": "dificil", "tags": ["Cardiologia", "Complicações Mecânicas", "Tamponamento", "IAM"]}', 57, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre a utilização de morfina no alívio da dor na SCA, estudos recentes (como o MOPID e registros observacionais) sugerem cautela. Qual o principal motivo dessa preocupação em relação à farmacocinética dos outros medicamentos da SCA?", "options": {"a": "A morfina causa hipertensão grave reflexa.", "b": "A morfina retarda a absorção e diminui o pico plasmático dos inibidores do receptor P2Y12 (ex: clopidogrel, ticagrelor), por lentificar o esvaziamento gástrico.", "c": "A morfina induz arritmias ventriculares fatais.", "d": "A morfina bloqueia diretamente o efeito da aspirina no fígado.", "e": "Não há evidência de interação negativa."}, "answer": "b", "rationale": "A morfina (e outros opioides) reduz a motilidade gástrica, o que retarda a absorção dos antiagregantes orais P2Y12. Isso pode deixar o paciente desprotegido contra a agregação plaquetária nas primeiras horas críticas do infarto.", "option_rationales": {"a": "Incorreta. Morfina tende a causar hipotensão.", "b": "Correta. Interação farmacocinética bem documentada.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Farmacologia", "Morfina", "SCA"]}', 58, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente admitido com dor torácica a 1 hora. O ECG de 12 derivações é inconclusivo (normal). No entanto, o médico decide realizar derivações extras (V7, V8 e V9) e observa um supra de ST de 1 mm nessas derivações. Qual a parede acometida e qual a artéria geralmente responsável?", "options": {"a": "Parede Anterior; Artéria Descendente Anterior.", "b": "Parede Posterior (ou Dorsal); Artéria Circunflexa ou Coronária Direita.", "c": "Ventrículo Direito; Artéria Coronária Direita.", "d": "Parede Lateral Alta; Ramo Diagonal.", "e": "Nó Sinusal; Artéria do Nó Sinusal."}, "answer": "b", "rationale": "As derivações V7-V9 avaliam a parede posterior/dorsal do VE. O infra de ST em V1-V3 no ECG padrão costuma ser a imagem em espelho dessa parede. A oclusão de ramos da Circunflexa (dominantemente) ou da ACD pode causar este tipo de infarto.", "option_rationales": {"a": "Incorreta. V1-V4 avaliam anterior.", "b": "Correta. Indica infarto dorsal, frequentemente ''invisível'' no ECG clássico.", "c": "Incorreta. V3R e V4R avaliam VD.", "d": "Incorreta. DI e aVL avaliam lateral alta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "ECG", "Infarto Posterior", "SCA"]}', 59, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O uso de oxigênio suplementar em pacientes com SCA deve ser criterioso. De acordo com o estudo DETO2X-AMI e o estudo AVOID, em pacientes com saturação de oxigênio (SpO2) normal, a hiperóxia pode ser prejudicial. Qual o ponto de corte de SpO2 para iniciar oxigênio e qual o efeito fisiológico deletério provável do O2 excessivo nas coronárias?", "options": {"a": "SpO2 < 90%; causa vasoconstrição coronária e aumento de radicais livres.", "b": "SpO2 < 98%; causa taquicardia.", "c": "SpO2 < 85%; causa relaxamento vascular excessivo.", "d": "SpO2 < 94%; causa hipoxemia paradoxal.", "e": "Deve ser dado a todos, independente da saturação."}, "answer": "a", "rationale": "Estudos mostraram que oxigênio em pacientes não hipoxêmicos (SpO2 > 90%) não reduz mortalidade e pode causar vasoconstrição coronária mediada por espécies reativas de oxigênio, podendo até aumentar a área do infarto.", "option_rationales": {"a": "Correta. Prática baseada em evidência atualizada.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Recomendação antiga ultrapassada."}, "difficulty": "media", "tags": ["Cardiologia", "Oxigênio", "SCA", "Diretrizes"]}', 60, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No contexto da síndrome coronariana aguda sem supra de ST, a indicação de estratégia invasiva IMEDIATA (em até 2 horas) está vinculada a quais achados clínicos?", "options": {"a": "Escore GRACE > 140 pontos.", "b": "Instabilidade hemodinâmica, choque cardiogênico, dor torácica persistente e refratária, ou arritmias ventriculares instáveis.", "c": "Diabetes Mellitus associado.", "d": "História familiar de morte súbita.", "e": "Qualquer elevação de troponina."}, "answer": "b", "rationale": "A estratégia invasiva de emergência (< 2h) é reservada para pacientes com critérios de extrema gravidade/instabilidade. Escore GRACE alto (> 140) indica estratégia precoce (em 24h), mas não necessariamente imediata se o paciente estiver estável.", "option_rationales": {"a": "Incorreta. Indica estratégia precoce (24h).", "b": "Correta. Critérios de gravidade máxima indicam ICP imediata.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "IAMssST", "Conduta", "Invasivo"]}', 61, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 42 anos, usuário crônico de cocaína, apresenta-se com dor torácica intensa há 30 minutos. O ECG revela supra de ST em parede anterior. Qual medicação, comumente usada no IAM, é CONTRAINDICADA na fase aguda da intoxicação por cocaína pelo risco de vasoespasmo coronariano paradoxal?", "options": {"a": "Betabloqueadores (ex: Propranolol, Atenolol).", "b": "Nitratos.", "c": "Aspirina.", "d": "Benzodiazepínicos.", "e": "Heparina."}, "answer": "a", "rationale": "Na intoxicação por cocaína, há estimulação alfa e beta-adrenérgica. O uso de betabloqueadores não seletivos deixa os receptores alfa sem oposição (unnopposed alpha stimulation), o que pode levar a um vasoespasmo coronariano grave e exacerbar a hipertensão sistêmica.", "option_rationales": {"a": "Correta. Betabloqueio é clássica contraindicação na dor torácica por cocaína.", "b": "Incorreta. São úteis pelo efeito vasodilatador.", "c": "Incorreta. Deve ser usada se houver suspeita de trombose de placa.", "d": "Incorreta. São o tratamento de escolha inicial para sedação e controle adrenérgico.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Cocaína", "Betabloqueador", "Vasoespasmo"]}', 62, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal limitação das estatinas de alta potência iniciadas precocemente no pós-infarto imediato para reduzir a inflamação vascular, conforme o estudo PROVE IT-TIMI 22?", "options": {"a": "Elas não funcionam nos primeiros 10 anos.", "b": "Podem causar rabdomiólise se não houver ajuste de dose na insuficiência hepática.", "c": "Dificultam a cicatrização do miocárdio infartado.", "d": "Aumentam o risco de AVC isquêmico.", "e": "Não há contraindicação, o benefício é máximo e deve-se atingir LDL alvo agressivo."}, "answer": "b", "rationale": "Embora o benefício seja altíssimo (pleiotropismo e redução de LDL), a principal limitação na prática são os efeitos adversos musculares e hepáticos, que exigem monitorização, embora raros em doses padrão.", "option_rationales": {"a": "Incorreta. O benefício começa em semanas.", "b": "Correta. Ponto de atenção na terapêutica com estatina potente.", "c": "Incorreta. Pelo contrário, ajudam na placa estável.", "d": "Incorreta. Elas reduzem o risco de AVC.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Estatinas", "Farmacologia", "SCA"]}', 63, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O padrão eletrocardiográfico de Wellens (tipo A ou B) é uma indicação clássica de qual patologia coronariana e qual a conduta contraindicada neste caso específico?", "options": {"a": "Estenose grave de artéria coronária direita; contraindicado realizar cateterismo.", "b": "Estenose crítica proximal de Artéria Descendente Anterior; contraindicado realizar teste de esforço elétrico (pelo risco de infarto anterior fatal).", "c": "Estenose de tronco de coronária esquerda; contraindicado aspirina.", "d": "Associação benigna com exercício; contraindicado repouso.", "e": "Padrão de Pericardite focal; contraindicado ibuprofeno."}, "answer": "b", "rationale": "A Síndrome de Wellens (ondas T invertidas profundas e simétricas ou bifásicas em V2-V3 no período sem dor) sinaliza oclusão subtotal crítica da DA proximal. Submeter este paciente a um teste de esforço pode precipitar uma oclusão total e um IAM anterior extenso.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Reconhecimento de Wellens e proibição de teste ergométrico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "ECG", "Wellens", "SCA"]}', 64, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente idosa, 82 anos, admitida com IAMssST de baixo risco. Durante a internação hospitalar, apresenta dor abdominal súbita, em cólica, desproporcional ao exame físico, logo após uma refeição leve. A gasometria revela acidose lática. Qual a principal suspeita de evento embólico/isquêmico sistêmico?", "options": {"a": "Colecistite aguda calculosa.", "b": "Apendicite aguda.", "c": "Isquemia Mesentérica Aguda (êmbolo de origem cardíaca ou aterotrombose mesentérica).", "d": "Infarto agudo de bexiga.", "e": "Hérnia umbilical encarcerada."}, "answer": "c", "rationale": "A dor abdominal desproporcional ao exame físico em pacientes vasculopatas/cardiopatas é sugestiva de isquemia mesentérica. O infarto pode ser fonte de coágulos (embolia) ou a própria baixa perfusão pode precipitar a isquemia em vasos já estenosados.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Emergência vascular abdominal pós-infarto.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Vascular", "Isquemia Mesentérica", "SCA"]}', 65, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 67 anos com história de IAM anterior prévio (fração de ejeção de 30%) é internado por descompensação de IC. Ele refere episódios de palpitações rápidas e tontura. O Holter revela episódios de Taquicardia Ventricular Não Sustentada (TVNS). Qual a melhor conduta para este paciente visando prevenção de morte súbita, conforme as diretrizes!", "options": {"a": "Apenas observar, pois a TVNS é benigna no pós-infarto.", "b": "Iniciar amiodarona profilática e nada mais.", "c": "Otimizar o tratamento da IC com BB, iECA/BRA, Espironolactona e se persistir, avaliar CDI (Cardiodesfibrilador Implantável).", "d": "Realizar ablação química do nó AV.", "e": "Prescrever digitálicos para controle da frequência."}, "answer": "c", "rationale": "A presença de TV e disfunção ventricular grave pós-infarto aumenta significativamente o risco de morte súbita. A estratégia principal é a terapia medicamentosa otimizada. O CDI é indicado em pacientes com FEVE ≤ 35% e classe funcional II/III (após 3 meses de tratamento estável) ou FEVE ≤ 30% classe I.", "option_rationales": {"a": "Incorreta. TVNS em coração doente nunca é benigna.", "b": "Incorreta. Amiodarona não reduz morte súbita melhor que o CDI.", "c": "Correta. Fluxo de tratamento preventivo pós-infarto.", "d": "Incorreta.", "e": "Incorreta. Digital aumenta o risco de arritmias ventriculares."}, "difficulty": "media", "tags": ["Cardiologia", "Arritmias", "CDI", "Pós-Infarto"]}', 66, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No tratamento do infarto agudo do miocárdio, o termo ''tempo porta-balão'' refere-se ao intervalo entre a chegada do paciente ao hospital e o quê?", "options": {"a": "A saída da ambulância da casa do paciente.", "b": "A abertura do vaso culpado através do insuflar do balão de angioplastia.", "c": "A administração da primeira dose de aspirina.", "d": "A realização do primeiro eletrocardiograma.", "e": "A entrada do paciente na enfermaria."}, "answer": "b", "rationale": "É o indicador de qualidade principal da rede de infarto. A meta é que esse tempo seja inferior a 90 minutos em hospitais com hemodinâmica (ou 120 min se houver transporte).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição técnica de tempo de reperfusão.", "c": "Incorreta.", "d": "Incorreta. Isso seria o tempo porta-ECG (meta < 10 min).", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Métricas", "SCA", "Tempo-Dependente"]}', 67, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O uso de Nitratos venosos (ex: nitroglicerina) na fase aguda da SCA está CONTRAINDICADO em qual situação clínica específica por risco de colapso circulatório?", "options": {"a": "IAM anterior extenso com hipertensão.", "b": "IAM de Ventrículo Direito ou uso recente de inibidores da fosfodiesterase-5 (ex: Sildenafila, Tadalafila).", "c": "Taquicardia sinusal intensa.", "d": "Presença de B3 na ausculta.", "e": "Cefaleia já presente."}, "answer": "b", "rationale": "Os nitratos reduzem a pré-carga. No infarto de VD, o ventrículo depende da pré-carga para funcionar. Os inibidores da 5-PDE potencializam o efeito vasodilatador do óxido nítrico dos nitratos, podendo levar a hipotensão grave e fatal.", "option_rationales": {"a": "Incorreta. É útil na hipertensão e congestão do IAM anterior.", "b": "Correta. Duas contraindicações absolutas vitais.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Nitrato causa cefaleia, mas não é contraindicação de morte."}, "difficulty": "media", "tags": ["Cardiologia", "Farmacologia", "Contraindicação", "VD"]}', 68, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 65 anos, admitido com IAMssST evoluindo com edema agudo de pulmão. A ausculta cardíaca revela um sopro holossistólico rude, 4+/6+, em borda esternal esquerda e no ápice, acompanhado de frêmito precordial. O pulmão tem estertores crepitantes até os ápices. Qual a complicação mecânica mais provável?", "options": {"a": "Insuficiência Mitral por ruptura de músculo papilar ou Comunicação Interventricular (CIV) pós-infarto.", "b": "Ruptura de parede livre.", "c": "Estenose Aórtica aguda.", "d": "Mixoma de átrio esquerdo.", "e": "Derrame pleural isolado."}, "answer": "a", "rationale": "Sopro holossistólico novo pós-infarto associado a congestão pulmonar grave indica ou insuficiência mitral aguda ou CIV. A CIV geralmente cursa com o frêmito em borda esternal. Ambas exigem suporte com BIA e correção cirúrgica urgente.", "option_rationales": {"a": "Correta. Diferencial crítico de sopro novo no infarto.", "b": "Incorreta. Ruptura de parede livre causa tamponamento, não sopro regurgitante.", "c": "Incorreta. Estenose aórtica não é complicação aguda do infarto.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Complicações Mecânicas", "Sopro Único", "SCA"]}', 69, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o diagnóstico de infarto agudo do miocárdio tipo 2, de acordo com a Quarta Definição Universal de Infarto, qual o mecanismo fisiopatológico central que o diferencia do tipo 1?", "options": {"a": "Ruptura ou erosão de placa aterosclerótica com trombo oclusivo.", "b": "Desbalanço entre a oferta e a demanda de oxigênio (ex: hipotensão grave, taquicardia, anemia profunda ou vasoespasmo) sem evento de placa agudo.", "c": "Relacionado apenas a procedimentos de cateterismo (ICP).", "d": "Relacionado a cirurgia cardíaca.", "e": "Morte súbita sem exames histopatológicos."}, "answer": "b", "rationale": "O infarto tipo 2 não é causado por acidente de placa coronariana (que é o tipo 1). Ele ocorre quando o coração sofre isquemia por causas secundárias (sepse, anemia, arritmias, espasmos) que aumentam o consumo de oxigênio ou diminuem a oferta drasticamente.", "option_rationales": {"a": "Incorreta. Definição do Tipo 1.", "b": "Correta. Definição do Tipo 2.", "c": "Incorreta. Seria Tipo 4a.", "d": "Incorreta. Seria Tipo 5.", "e": "Incorreta. Seria Tipo 3."}, "difficulty": "media", "tags": ["Cardiologia", "Definição de Infarto", "SCA", "Fisiopatologia"]}', 70, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma lesão de 70% na DA. O médico decide realizar uma Reserva de Fluxo Fracionada (FFR). Qual valor de FFR indica que a lesão é funcionalmente significante e justifica a revascularização?", "options": {"a": "FFR > 1,0.", "b": "FFR ≤ 0,80.", "c": "FFR > 0,95.", "d": "FFR ≤ 0,50 apenas.", "e": "Qualquer valor de FFR indica tratamento."}, "answer": "b", "rationale": "O FFR avalia o gradiente de pressão através de uma estenose coronariana sob hiperemia máxima. Um valor ≤ 0,80 indica que a lesão causa isquemia significativa e deve ser tratada. Valores > 0,80 podem ser manejados clinicamente de forma segura (estudos FAME e DEFER).", "option_rationales": {"a": "Incorreta. Valor impossível fisicamente através da estenose.", "b": "Correta. Ponto de corte clássico das diretrizes.", "c": "Incorreta.", "d": "Incorreta. 0,50 é muito grave, mas 0,80 já justifica conduta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "FFR", "Isquemia Funcional", "Hemodinâmica"]}', 71, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 35 anos, tabagista, com dor torácica recorrente e repolarização precoce no ECG. Apresenta troponina ultrassensível ligeiramente elevada (10x o limite superior). RM cardíaca mostra realce tardio sub-epicárdico com padrão em ''mapa-mundi'' e edema miocárdico. Coronárias normais. Qual o diagnóstico mais provável?", "options": {"a": "Infarto tipo 1.", "b": "Miocardite Aguda.", "c": "Takotsubo.", "d": "MCH.", "e": "Arritmia idiopática."}, "answer": "b", "rationale": "O padrão de realce tardio sub-epicárdico ou mesocárdico na RM é característico de miocardite, diferenciando-se do infarto (que é sempre sub-endocárdico ou transmural). O edema miocárdico confirma a fase aguda.", "option_rationales": {"a": "Incorreta. Realce no infarto é sub-endocárdico.", "b": "Correta. RM é padrão-ouro não invasivo para miocardite.", "c": "Incorreta. Takotsubo geralmente não tem realce tardio ou o tem de forma muito sutil; acomete o ápice.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Ressonância", "Miocardite", "Diferencial"]}', 72, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A Síndrome de Takotsubo (ou cardiomiopatia por estresse) mimetiza um infarto agudo. Qual o achado típico na ventriculografia esquerda e qual o gatilho emocional ou físico frequentemente associado?", "options": {"a": "Dilatação basal; excesso de exercício.", "b": "Acinésia ou discinésia apical com balonamento do ventrículo esquerdo (aspecto de armadilha de polvo); estresse emocional intenso.", "c": "Hipertrofia septal; repouso prolongado.", "d": "Ventrículo esquerdo pequeno; infecção pulmonar.", "e": "Ruptura de cordoalha; sem gatilho."}, "answer": "b", "rationale": "A síndrome de Takotsubo envolve uma disfunção ventricular transitória, geralmente poupando a base e afetando o ápice (apical ballooning). A causa exata é incerta, mas acredita-se ser uma tempestade de catecolaminas pós-estresse.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Descrição clássica da síndrome do coração partido.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Takotsubo", "SCA", "Diferencial"]}', 73, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a medicação de primeira linha para o tratamento da dor na Pericardite Aguda em um paciente que NÃO teve infarto recente?", "options": {"a": "Opioides potentes.", "b": "Anti-inflamatórios não esteroidais (AINEs) em doses altas (ex: Ibuprofeno 600 mg 8/8h).", "c": "Corticoides sistêmicos.", "d": "Amiodarona.", "e": "Varfarina."}, "answer": "b", "rationale": "AINEs são o pilar do tratamento. Se o paciente tivesse tido infarto recente, o AINE de escolha seria obrigatoriamente o AAS em doses altas, para não interferir na cicatrização miocárdica e evitar ruptura (teórico).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento anti-inflamatório é a base.", "c": "Incorreta. Reservado para casos refratários ou autoimunes.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Pericardite", "AINEs", "Conduta"]}', 74, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No paciente com IAMCSST, se a Intervenção Coronária Percutânea (ICP) primária não puder ser realizada em até 120 minutos do primeiro contato médico, a fibrinólise deve ser realizada se não houver contraindicações. Em quanto tempo após a decisão ela deve ser iniciada (tempo porta-agulha)?", "options": {"a": "60 minutos.", "b": "30 minutos.", "c": "10 minutos.", "d": "120 minutos.", "e": "Não há pressa."}, "answer": "c", "rationale": "A agilidade na fibrinólise é crucial. O tempo ideal (porta-agulha ou primeiro contato médico-agulha) é de até 10 minutos (algumas diretrizes anteriores diziam 30 min, mas a meta atual é o mais precoce possível, idealmente pré-hospitalar ou em 10 min pós-diagnóstico).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. 30 min era a meta antiga; a atual (< 10 min) é mais rigorosa.", "c": "Correta. Meta atual para início do fibrinolítico.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Métricas", "Fibrinólise", "Tempo-Dependente"]}', 75, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 60 anos, pós-infarto inferior (oclusão de ACD). Durante o cateterismo de seguimento, identifica-se lesão de 70% em Artéria Descendente Anterior. O paciente é assintomático. Qual critério anatômico de revascularização (SYNTAX, ISCHEMIA) favorece a manutenção do tratamento clínico?", "options": {"a": "Escore SYNTAX muito elevado.", "b": "Estudo ISCHEMIA: pacientes com doença estável e isquemia moderada/grave sem lesão de tronco não tiveram redução de morte ou IAM com revascularização precoce vs tratamento clínico otimizado.", "c": "Diabetes mellitus presente.", "d": "Hipotensão.", "e": "Idade avançada."}, "answer": "b", "rationale": "O estudo ISCHEMIA mudou o paradigma da doença coronária estável, mostrando que o tratamento clínico otimizado é uma estratégia inicial segura para a maioria dos pacientes, exceto aqueles com lesão de Tronco de Esquerda ou sintomas refratários.", "option_rationales": {"a": "Incorreta. SYNTAX elevado favorece a cirurgia se fosse revascularizar.", "b": "Correta. Conhecimento de grandes ensaios clínicos modernos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "ISCHEMIA", "Evidência", "SCA"]}', 76, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A imagem de ''pseudonormalização'' da onda T no ECG de um paciente com dor torácica recorrente sugere:", "options": {"a": "Melhora definitiva da isquemia.", "b": "Isquemia miocárdica aguda em evolução (re-oclusão ou isquemia persistente).", "c": "Padrão normal do atleta.", "d": "Erro de técnica na realização do exame.", "e": "Efeito colateral do betabloqueador."}, "answer": "b", "rationale": "Quando um paciente tem inversão crônica de onda T por isquemia prévia e, durante um novo episódio de dor, a onda T torna-se positiva (normaliza), isso paradoxalmente indica isquemia aguda grave (transmural), sendo um sinal de alerta crítico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Sinal eletrocardiográfico sutil de isquemia ativa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "ECG", "Pseudonormalização", "SCA"]}', 77, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No contexto da revascularização cirúrgica (CRVM), qual o enxerto arterial que apresenta a maior patência no longo prazo (10 anos)?", "options": {"a": "Veia safena interna.", "b": "Artéria mamária interna esquerda (torácica interna).", "c": "Artéria radial.", "d": "Artéria epigástrica.", "e": "Prótese de Teflon."}, "answer": "b", "rationale": "A artéria mamária interna esquerda anastomosada para a descendente anterior é o ''padrão-ouro'' da cirurgia cardíaca, com taxas de patência superiores a 90-95% em 10 anos, reduzindo mortalidade.", "option_rationales": {"a": "Incorreta. Safena tem alta taxa de oclusão (50% em 10 anos).", "b": "Correta. Melhor enxerto conhecido.", "c": "Incorreta. Radial é boa, mas inferior à mamária.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "CRVM", "Enxertos", "Mortalidade"]}', 78, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 70 anos apresenta-se com insuficiência cardíaca subaguda 2 semanas após um quadro de dor torácica ignorado. O ecocardiograma mostra uma área de acinésia na parede anterior com imagem de trombo nela aderido. Qual a principal recomendação para prevenir fenômenos embólicos sistêmicos (AVC)?", "options": {"a": "Anticoagulação plena (Varfarina por 3 a 6 meses ou NOAC conforme evidência recente).", "b": "Apenas Aspirina 100 mg.", "c": "Uso de estatinas em dose alta.", "d": "Fibrinólise do trombo ventricular.", "e": "Cirurgia para remoção do trombo imediatamente."}, "answer": "a", "rationale": "O trombo ventricular esquerdo pós-infarto tem alto risco de embolização. A recomendação é a anticoagulação prolongada (3 a 6 meses) até que o trombo se organize ou desapareça e a área de acinésia seja reavaliada.", "option_rationales": {"a": "Correta. Manejo padrão para prevenção secundária de embolia.", "b": "Incorreta. Insuficiente para trombo cavitário.", "c": "Incorreta.", "d": "Incorreta. Risco de fragmentação e AVC.", "e": "Incorreta. Muito invasivo para conduta inicial estável."}, "difficulty": "moderada", "tags": ["Cardiologia", "Trombo de VE", "Anticoagulação", "Complicações"]}', 79, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A pericardite urêmica (em pacientes com insuficiência renal dialítica) difere da pericardite viral clássica por qual característica clínica/eletrocardiográfica?", "options": {"a": "Causa supra de ST mais intenso.", "b": "Frequentemente NÃO cursa com supra de ST no ECG (por ser uma reação química/fibrinosa sem inflamação epicárdica subjacente intensa).", "c": "Causa dor que melhora ao tossir.", "d": "Ocorre apenas em crianças.", "e": "É sempre acompanhada de rash cutâneo."}, "answer": "b", "rationale": "Na pericardite urêmica, as alterações clássicas do ST são menos frequentes porque o processo é mais fibrinoso/hemorrágico do que inflamatório difuso envolvendo o miocárdio subepicárdico (que é quem gera a corrente de lesão do supra). O tratamento é a diálise intensiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Achado específico da uremia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "Nefrologia", "Pericardite Urêmica", "Diferencial"]}', 80, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Em pacientes com infarto inferior, a derivação V4R apresenta supra de ST de 1 mm. Qual o significado e qual a conduta terapêutica que deve ser PRIORIZADA?", "options": {"a": "Infarto de VD; priorizar expansão volêmica com cristaloides (para garantir pré-carga do VD).", "b": "Infarto lateral; priorizar furosemida.", "c": "Infarto de átrio; priorizar digital.", "d": "Bloqueio de ramo; priorizar marcapasso.", "e": "Normalidade."}, "answer": "a", "rationale": "V4R positivo em infarto inferior é altamente sensível e específico para acometimento do VD. A conduta clássica envolve manter a pré-carga (volume) e evitar vasodilatadores (nitratos, morfina, diuréticos).", "option_rationales": {"a": "Correta. Reconhecimento e manejo hemodinâmico do infarto de VD.", "b": "Incorreta. Furosemida pode causar choque no infarto de VD.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Infarto de VD", "Volume", "SCA"]}', 81, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre a classificação de Killip no infarto agudo do miocárdio, o que define um paciente em Killip III?", "options": {"a": "Ausência de sinais de insuficiência cardíaca.", "b": "Presença de estertores crepitantes em menos de metade dos pulmões ou presença de B3.", "c": "Edema agudo de pulmão (estertores em mais de metade dos campos pulmonares).", "d": "Choque cardiogênico.", "e": "Morte súbita."}, "answer": "c", "rationale": "Killip I: Sem sinal de IC. Killip II: Estertores basais ou B3. Killip III: Edema agudo de pulmão. Killip IV: Choque cardiogênico.", "option_rationales": {"a": "Incorreta. Killip I.", "b": "Incorreta. Killip II.", "c": "Correta. Definição clássica pragmática.", "d": "Incorreta. Killip IV.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Killip", "Prognóstico", "SCA"]}', 82, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente tabagista, hipertenso, de 50 anos, tem dor torácica aos esforços. O ecocardiograma de estresse com dobutamina revela acinésia de parede anterior apenas em altas doses de dobutamina, que recupera após a suspensão da droga. Esse tecido miocárdico é chamado de:", "options": {"a": "Miocárdio Infartado (morto).", "b": "Miocárdio Hibernado (disfunção crônica por baixa oferta crônica).", "c": "Miocárdio Atordoado (Stunned - disfunção transitória após reperfusão).", "d": "Miocárdio Isquêmico com reserva contrátil.", "e": "Miocárdio Hipertrófico."}, "answer": "d", "rationale": "O miocárdio que apresenta isquemia induzida pelo estresse (Dobutamina) mas que é normal em repouso é miocárdio isquêmico. Hibernação refere-se a miocárdio com disfunção de repouso que recupera com revascularização. Atordoamento ocorre após um insulto agudo de curta duração seguido de reperfusão.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Correta. Resposta contrátil ao estresse vs isquemia.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Viabilidade", "Ecocardiograma", "Fisiologia"]}', 83, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A ''Angina de Ludwig'' é um diagnóstico diferencial importante de dor cervical/mandibular. No entanto, qual a sua origem fisiopatológica, que a diferencia totalmente da angina coronariana?", "options": {"a": "Infarto da mandíbula.", "b": "Infecção bacteriana multibacteriana do espaço submandibular e sublingual (celulite grave), geralmente de origem dentária.", "c": "Espasmo do esôfago.", "d": "Refluxo gastroesofágico.", "e": "Inflamação da glândula tireoide."}, "answer": "b", "rationale": "Embora o nome ''Angina'' sugira aperto no peito, a Angina de Ludwig é uma emergência infecciosa em cirurgia de cabeça e pescoço, podendo causar obstrução de via aérea. É importante não confundir com angina pectoris.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diferencial anatômico e etiológico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Medicina", "Diferencial", "Infectologia", "Vias Aéreas"]}', 84, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Em pacientes submetidos a ICP, o risco de lesão renal induzida por contraste (Nefropatia por Contraste) pode ser mitigado através de qual medida com maior evidência de benefício?", "options": {"a": "Uso de N-acetilcisteína oral.", "b": "Hidratação venosa vigorosa com solução salina isotônica (0,9%) antes e depois do procedimento (se não houver contraindicação por IC).", "c": "Uso profilático de diuréticos de alça.", "d": "Uso de bicarbonato de sódio universalmente.", "e": "Realizar cateterismo sem contraste (apenas por ultrassom)."}, "answer": "b", "rationale": "A hidratação peri-procedimento é a única medida largamente aceita e comprovada para reduzir a incidência de lesão renal aguda por contraste radiológico. N-acetilcisteína e bicarbonato tiveram resultados conflitantes (estudo PRESERVE).", "option_rationales": {"a": "Incorreta. Evidência fraca ou nula.", "b": "Correta. Pilar da prevenção.", "c": "Incorreta. Desidrata e piora a nefrotoxicidade.", "d": "Incorreta. Não superior ao soro fisiológico.", "e": "Incorreta. Praticamente impossível na maioria dos procedimentos coronários."}, "difficulty": "moderada", "tags": ["Cardiologia", "Nefrologia", "Segurança", "Contraste"]}', 85, 'draft');
